import numpy as np

def step_decay(epoch, initial_lr=0.1, drop_factor=0.5, epochs_per_drop=10):
    return initial_lr * (drop_factor ** (epoch // epochs_per_drop))

def exponential_decay(epoch, initial_lr=0.1, decay_rate=0.05):
    return initial_lr * np.exp(-decay_rate * epoch)

def cosine_annealing(epoch, initial_lr=0.1, total_epochs=50):
    return initial_lr * 0.5 * (1 + np.cos(np.pi * epoch / total_epochs))

print("Epoch | Step Decay | Exponential Decay | Cosine Annealing")
for epoch in [0, 10, 20, 30, 40, 49]:
    step_lr = step_decay(epoch)
    exp_lr = exponential_decay(epoch)
    cos_lr = cosine_annealing(epoch)
    print(f"  {epoch:3d} |   {step_lr:.5f}  |      {exp_lr:.5f}      |     {cos_lr:.5f}")

print("\nNotice step decay drops in sudden jumps, exponential decay shrinks smoothly and continuously,")
print("and cosine annealing follows its own distinctive, smooth curve toward genuinely near zero")
